const {test}=require('node:test');const assert=require('node:assert/strict');
async function setup(){return {T:await import('../vendor/three.module.js'),M:await import('../inertia-layers.mjs')};}
test('all layers default on; terrain excluded and nested actors included',async()=>{const {T,M}=await setup(),root=new T.Group(),terrain=new T.Mesh(),object=new T.Group(),scenery=new T.Group(),people=new T.Group(),person=new T.Group();object.userData.motionKey='house';scenery.userData.motionKey='dressing-0';person.userData.inertiaLayer='people';root.add(terrain,object,scenery,people);people.add(person);assert.deepEqual(M.defaultLayers(),{people:true,objects:true,scenery:true});assert.deepEqual(M.collectInertia(root).map(r=>r.layer),['objects','scenery','people']);});
test('semantic parent assembly prevents double transforms of child parts',async()=>{const {T,M}=await setup(),root=new T.Group(),house=new T.Group(),part=new T.Group();root.add(house);house.add(part);house.userData.motionKey='house';part.userData.motionKey='roof';assert.equal(M.collectInertia(root).length,1);});
test('nested scale and rotation preserve world-space response',async()=>{const {T,M}=await setup(),root=new T.Group(),parent=new T.Group(),a=new T.Group(),b=new T.Group();a.userData.inertiaLayer=b.userData.inertiaLayer='people';parent.scale.setScalar(.1);parent.rotation.y=Math.PI/2;root.add(a,parent);parent.add(b);const records=M.collectInertia(root);M.stepInertia(records,.016,{dx:1});root.updateMatrixWorld(true);assert.ok(a.getWorldPosition(new T.Vector3()).distanceTo(b.getWorldPosition(new T.Vector3()))<1e-8);assert.ok(a.position.x<0);});
test('individual layer off restores only that layer; reduced motion restores all',async()=>{const {T,M}=await setup(),root=new T.Group();for(const layer of M.INERTIA_LAYERS){const o=new T.Group();o.userData.inertiaLayer=layer;root.add(o);}const records=M.collectInertia(root);M.stepInertia(records,.016,{dx:1,layers:{people:false,objects:true,scenery:true}});assert.equal(records[0].o.position.x,0);assert.ok(records[1].o.position.x<0);M.stepInertia(records,.016,{dx:1,reduced:true});for(const r of records)assert.deepEqual(r.o.position.toArray(),[0,0,0]);});
test('vertical pull excites inertia without changing source transform snapshots',async()=>{const {T,M}=await setup(),root=new T.Group(),o=new T.Group();root.add(o);o.userData.inertiaLayer='people';o.position.set(1,2,3);const records=M.collectInertia(root);M.stepInertia(records,.016,{dy:2});assert.notEqual(o.position.z,3);assert.deepEqual(records[0].base.toArray(),[1,2,3]);});
test('wiggling a lifted tile excites contents through its full transform and settles at rest',async()=>{const {T,M}=await setup(),tile=new T.Group(),root=new T.Group(),object=new T.Group();tile.add(root);root.add(object);object.position.set(2,1,0);object.userData.motionKey='house';const records=M.collectInertia(root);tile.rotation.z=.12;tile.scale.y=1.08;M.stepInertia(records,1/60,{trackTransforms:true});assert.ok(Math.hypot(records[0].body.x,records[0].body.z)>.03);tile.position.x=.8;M.stepInertia(records,1/60,{trackTransforms:true});assert.ok(records[0].body.x<-.1);tile.position.x=0;M.stepInertia(records,1/60,{trackTransforms:true});assert.ok(Number.isFinite(records[0].body.x));for(let i=0;i<600;i++)M.stepInertia(records,1/60,{trackTransforms:true});assert.ok(Math.hypot(records[0].body.x,records[0].body.z)<.001);});
test('batched scenery splits per authored object only in the copy and keeps source geometry unchanged',async()=>{const {T,M}=await setup(),root=new T.Group(),sector=new T.Group();root.add(sector);sector.userData.motionKey='dressing-0';const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute([1,0,0,1,1,0,2,0,0,3,0,0,3,1,0,4,0,0],3));const mesh=new T.Mesh(geometry,new T.MeshBasicMaterial());mesh.userData.inertiaParts=[{key:'tree',anchor:[1,0,0],start:0,count:3},{key:'rock',anchor:[3,0,0],start:3,count:3}];sector.add(mesh);const copy=root.clone(true),records=M.collectInertia(copy);assert.equal(records.length,2);assert(records.every(r=>r.layer==='scenery'));assert.equal(sector.children.length,1);assert.equal(mesh.visible,true);M.stepInertia(records,.016,{dx:1});assert.notEqual(records[0].body.x,records[1].body.x);assert.deepEqual(Array.from(geometry.getAttribute('position').array),[1,0,0,1,1,0,2,0,0,3,0,0,3,1,0,4,0,0]);});
